/// Action H2a "Lower Data Classification" -- prepare replay
/// authority. Fresh root, not an extension of the single, already-complex
/// `action_replay_operations` table every other Action operation (H1 and
/// H2a alike) shares -- that table's `operation`/`result_kind` CHECK and its
/// many generated FK-binding columns make a safe recreate far riskier here
/// than anywhere else this pass, and this operation needs none of its
/// terminal-cause tracking (see V31's doc comment).
///
/// `operation_ordinal`, however, is NOT independent: every Action capsule
/// funnels through the ONE `action_replay_operations` table today, whose own
/// `action_replay_operations_contiguous_insert` trigger enforces gapless
/// ordinals -- and 6 existing repository call sites each compute their own
/// next ordinal via a bare `SELECT MAX(operation_ordinal)+1 FROM
/// action_replay_operations`. Widening this operation's ordinals into that
/// same global sequence means both DROP-and-recreate-wider triggers on both
/// tables (mirroring Decision's V26/V27 technique) AND updating those 6
/// existing queries in the same commit as this migration -- otherwise a
/// later H1/Accept operation would compute a next-ordinal value that already
/// collides with one this operation just claimed.
pub(super) const V30_ACTION_H2A_LOWER_CLASSIFICATION_PREPARE_SQL: &str = r#"
DROP TRIGGER action_replay_operations_contiguous_insert;
CREATE TABLE action_h2a_lower_classification_prepare_replay_operations(idempotency_id TEXT PRIMARY KEY,operation TEXT NOT NULL CHECK(operation='prepare_lower_classification'),correlation_id TEXT NOT NULL CHECK(length(correlation_id)>0),operation_ordinal INTEGER NOT NULL UNIQUE CHECK(operation_ordinal>=0),result_kind TEXT NOT NULL CHECK(result_kind='prepared'),result_reference TEXT NOT NULL REFERENCES prepared_intents(id),UNIQUE(idempotency_id,operation),UNIQUE(idempotency_id,correlation_id),FOREIGN KEY(idempotency_id,operation) REFERENCES action_h2a_lower_classification_command_prepares(idempotency_id,command_kind) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TABLE action_h2a_lower_classification_command_prepares(idempotency_id TEXT PRIMARY KEY,command_kind TEXT GENERATED ALWAYS AS ('prepare_lower_classification') STORED,action_id TEXT NOT NULL REFERENCES actions(id),expected_version INTEGER NOT NULL CHECK(expected_version>0),proposed_classification TEXT NOT NULL CHECK(proposed_classification IN ('public','internal','confidential','restricted','unclassified')),rationale TEXT NOT NULL,UNIQUE(idempotency_id,command_kind),FOREIGN KEY(idempotency_id,command_kind) REFERENCES action_h2a_lower_classification_prepare_replay_operations(idempotency_id,operation)) STRICT;
CREATE TABLE action_h2a_lower_classification_prepare_replay_audits(idempotency_id TEXT NOT NULL REFERENCES action_h2a_lower_classification_prepare_replay_operations(idempotency_id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),audit_event_id TEXT NOT NULL UNIQUE REFERENCES audit_events(id),correlation_id TEXT NOT NULL,PRIMARY KEY(idempotency_id,ordinal),FOREIGN KEY(audit_event_id,correlation_id) REFERENCES audit_events(id,correlation_id),FOREIGN KEY(idempotency_id,correlation_id) REFERENCES action_h2a_lower_classification_prepare_replay_operations(idempotency_id,correlation_id)) STRICT;
CREATE TRIGGER ledger_idempotency_claim_action_h2a_lower_classification_prepare AFTER INSERT ON action_h2a_lower_classification_prepare_replay_operations BEGIN INSERT INTO ledger_idempotency_claims(idempotency_id,namespace,operation) VALUES(NEW.idempotency_id,'action',NEW.operation); END;
CREATE TRIGGER action_replay_operations_contiguous_v30 BEFORE INSERT ON action_replay_operations WHEN NEW.operation_ordinal != COALESCE((SELECT MAX(operation_ordinal)+1 FROM (SELECT operation_ordinal FROM action_replay_operations UNION ALL SELECT operation_ordinal FROM action_h2a_lower_classification_prepare_replay_operations)),0) BEGIN SELECT RAISE(ABORT,'action replay operation ordinals must be globally contiguous from zero'); END;
CREATE TRIGGER action_h2a_lower_classification_prepare_replay_operations_contiguous_v30 BEFORE INSERT ON action_h2a_lower_classification_prepare_replay_operations WHEN NEW.operation_ordinal != COALESCE((SELECT MAX(operation_ordinal)+1 FROM (SELECT operation_ordinal FROM action_replay_operations UNION ALL SELECT operation_ordinal FROM action_h2a_lower_classification_prepare_replay_operations)),0) BEGIN SELECT RAISE(ABORT,'action replay operation ordinals must be globally contiguous from zero'); END;
CREATE TRIGGER action_h2a_lower_classification_prepare_replay_operations_ordinal_immutable BEFORE UPDATE OF operation_ordinal ON action_h2a_lower_classification_prepare_replay_operations WHEN NEW.operation_ordinal != OLD.operation_ordinal BEGIN SELECT RAISE(ABORT,'action H2a lower-classification prepare operation ordinals are immutable'); END;
CREATE INDEX idx_action_h2a_lower_classification_prepare_replay_ordinal ON action_h2a_lower_classification_prepare_replay_operations(operation_ordinal);
CREATE INDEX idx_action_h2a_lower_classification_prepare_replay_correlation ON action_h2a_lower_classification_prepare_replay_operations(correlation_id);
"#;

/// Action H2a "Lower Data Classification" -- execute success
/// replay authority. No terminal-denial table: `actions.rs`'s own
/// `approve_and_execute_lower_action_classification` doc comment explains
/// this operation deliberately does NOT reuse `record_h2_failure`/
/// `record_retryable_preview_failure` -- a failed attempt simply
/// re-validates on retry rather than being remembered, "a safe
/// simplification, not a partial correctness bug" -- so unlike Accept/
/// Complete/Cancel/Reopen this operation never produces a durable
/// `ActionPersistenceResult::Terminal` capsule at all. Widens V30's global
/// ordinal union to a third table by the same DROP-and-recreate-wider
/// technique.
pub(super) const V31_ACTION_H2A_LOWER_CLASSIFICATION_EXECUTE_SQL: &str = r#"
DROP TRIGGER action_replay_operations_contiguous_v30;
DROP TRIGGER action_h2a_lower_classification_prepare_replay_operations_contiguous_v30;
CREATE TABLE action_h2a_lower_classification_execute_replay_operations(idempotency_id TEXT PRIMARY KEY,operation TEXT NOT NULL CHECK(operation='execute_lower_classification'),correlation_id TEXT NOT NULL CHECK(length(correlation_id)>0),operation_ordinal INTEGER NOT NULL UNIQUE CHECK(operation_ordinal>=0),result_kind TEXT NOT NULL CHECK(result_kind='lowered'),action_id TEXT NOT NULL REFERENCES actions(id),prepared_intent_id TEXT NOT NULL REFERENCES prepared_intents(id),approval_receipt_id TEXT NOT NULL UNIQUE REFERENCES approval_receipts(id),UNIQUE(idempotency_id,operation),UNIQUE(idempotency_id,correlation_id),UNIQUE(idempotency_id,prepared_intent_id),FOREIGN KEY(idempotency_id,operation) REFERENCES action_h2a_lower_classification_command_executes(idempotency_id,command_kind) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TABLE action_h2a_lower_classification_command_executes(idempotency_id TEXT PRIMARY KEY,command_kind TEXT GENERATED ALWAYS AS ('execute_lower_classification') STORED,prepared_id TEXT NOT NULL REFERENCES prepared_intents(id),actor TEXT NOT NULL CHECK(actor='head_of_products'),acknowledged_digest TEXT NOT NULL,UNIQUE(idempotency_id,command_kind),FOREIGN KEY(idempotency_id,command_kind) REFERENCES action_h2a_lower_classification_execute_replay_operations(idempotency_id,operation)) STRICT;
CREATE TABLE action_h2a_lower_classification_execute_replay_audits(idempotency_id TEXT NOT NULL REFERENCES action_h2a_lower_classification_execute_replay_operations(idempotency_id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),audit_event_id TEXT NOT NULL UNIQUE REFERENCES audit_events(id),correlation_id TEXT NOT NULL,PRIMARY KEY(idempotency_id,ordinal),FOREIGN KEY(audit_event_id,correlation_id) REFERENCES audit_events(id,correlation_id),FOREIGN KEY(idempotency_id,correlation_id) REFERENCES action_h2a_lower_classification_execute_replay_operations(idempotency_id,correlation_id)) STRICT;
CREATE TRIGGER ledger_idempotency_claim_action_h2a_lower_classification_execute AFTER INSERT ON action_h2a_lower_classification_execute_replay_operations BEGIN INSERT INTO ledger_idempotency_claims(idempotency_id,namespace,operation) VALUES(NEW.idempotency_id,'action',NEW.operation); END;
CREATE TRIGGER action_replay_operations_contiguous_v31 BEFORE INSERT ON action_replay_operations WHEN NEW.operation_ordinal != COALESCE((SELECT MAX(operation_ordinal)+1 FROM (SELECT operation_ordinal FROM action_replay_operations UNION ALL SELECT operation_ordinal FROM action_h2a_lower_classification_prepare_replay_operations UNION ALL SELECT operation_ordinal FROM action_h2a_lower_classification_execute_replay_operations)),0) BEGIN SELECT RAISE(ABORT,'action replay operation ordinals must be globally contiguous from zero'); END;
CREATE TRIGGER action_h2a_lower_classification_prepare_replay_operations_contiguous_v31 BEFORE INSERT ON action_h2a_lower_classification_prepare_replay_operations WHEN NEW.operation_ordinal != COALESCE((SELECT MAX(operation_ordinal)+1 FROM (SELECT operation_ordinal FROM action_replay_operations UNION ALL SELECT operation_ordinal FROM action_h2a_lower_classification_prepare_replay_operations UNION ALL SELECT operation_ordinal FROM action_h2a_lower_classification_execute_replay_operations)),0) BEGIN SELECT RAISE(ABORT,'action replay operation ordinals must be globally contiguous from zero'); END;
CREATE TRIGGER action_h2a_lower_classification_execute_replay_operations_contiguous_v31 BEFORE INSERT ON action_h2a_lower_classification_execute_replay_operations WHEN NEW.operation_ordinal != COALESCE((SELECT MAX(operation_ordinal)+1 FROM (SELECT operation_ordinal FROM action_replay_operations UNION ALL SELECT operation_ordinal FROM action_h2a_lower_classification_prepare_replay_operations UNION ALL SELECT operation_ordinal FROM action_h2a_lower_classification_execute_replay_operations)),0) BEGIN SELECT RAISE(ABORT,'action replay operation ordinals must be globally contiguous from zero'); END;
CREATE TRIGGER action_h2a_lower_classification_execute_replay_operations_ordinal_immutable BEFORE UPDATE OF operation_ordinal ON action_h2a_lower_classification_execute_replay_operations WHEN NEW.operation_ordinal != OLD.operation_ordinal BEGIN SELECT RAISE(ABORT,'action H2a lower-classification execute operation ordinals are immutable'); END;
CREATE INDEX idx_action_h2a_lower_classification_execute_replay_ordinal ON action_h2a_lower_classification_execute_replay_operations(operation_ordinal);
CREATE INDEX idx_action_h2a_lower_classification_execute_replay_correlation ON action_h2a_lower_classification_execute_replay_operations(correlation_id);
"#;

/// Delivery family (Initiative/Project/Milestone) H2a "Lower Data
/// Classification" -- widens `prepared_intents.intent_kind` and
/// `prepared_intent_targets.target_type` for the three new kinds, matching
/// V23's/V22's identical recreate-table technique. `prepared_intent_targets`
/// was last widened in V22 (Portfolio siblings); Action/Decision/Risk/Issue's
/// own H2a work never needed to touch it since their target types existed
/// since V1.
pub(super) const V32_DELIVERY_H2A_LOWER_CLASSIFICATION_PREPARED_INTENT_KINDS_SQL: &str = r#"
DROP TRIGGER risk_h2a_v11_terminal_denials_topology_insert;
DROP TRIGGER decision_h2a_prepared_intent_kind_insert;
DROP TRIGGER decision_h2a_prepared_intent_kind_update;
DROP TRIGGER risk_h2a_lower_classification_terminal_denials_topology_insert;
CREATE TABLE prepared_intents_v32(id TEXT PRIMARY KEY,contract_version INTEGER NOT NULL CHECK(contract_version>0),intent_kind TEXT NOT NULL CHECK(intent_kind IN ('accept_action_request','resolve_decision_request','complete_action','cancel_action','reopen_action','supersede_decision','record_risk_occurrence','close_risk','resolve_issue','close_issue','reopen_issue','relationship.remove','lower_portfolio_classification','lower_product_classification','lower_roadmap_classification','lower_kpi_classification','lower_kpi_observation_classification','lower_action_classification','lower_decision_classification','lower_risk_classification','lower_issue_classification','lower_initiative_classification','lower_project_classification','lower_milestone_classification')),payload_digest TEXT NOT NULL,classification TEXT NOT NULL CHECK(classification IN ('public','internal','confidential','restricted','unclassified')),policy TEXT NOT NULL CHECK(policy='allowed'),cancellation_policy TEXT NOT NULL CHECK(cancellation_policy='not_cancellable_after_submit'),authority TEXT NOT NULL CHECK(authority='head_of_products'),support_id TEXT REFERENCES support_witnesses(id),confirmation_challenge TEXT,expires_at INTEGER NOT NULL CHECK(expires_at>=0),created_at INTEGER NOT NULL CHECK(created_at>=0),consumed_at INTEGER CHECK(consumed_at>=created_at),UNIQUE(id,payload_digest)) STRICT;
INSERT INTO prepared_intents_v32 SELECT * FROM prepared_intents;
DROP TABLE prepared_intents;
ALTER TABLE prepared_intents_v32 RENAME TO prepared_intents;
CREATE TABLE prepared_intent_targets_v32(prepared_intent_id TEXT NOT NULL REFERENCES prepared_intents(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),target_type TEXT NOT NULL CHECK(target_type IN ('action_request','action','decision_request','decision','risk','issue','relationship','portfolio','product','roadmap','kpi','kpi_observation','initiative','project','milestone')),target_id TEXT NOT NULL,expected_version INTEGER NOT NULL CHECK(expected_version>=0),PRIMARY KEY(prepared_intent_id,ordinal)) STRICT;
INSERT INTO prepared_intent_targets_v32 SELECT * FROM prepared_intent_targets;
DROP TABLE prepared_intent_targets;
ALTER TABLE prepared_intent_targets_v32 RENAME TO prepared_intent_targets;
CREATE INDEX idx_prepared_intents_expires_at ON prepared_intents(expires_at);
CREATE TRIGGER risk_h2a_v11_terminal_denials_topology_insert BEFORE INSERT ON risk_h2a_v11_terminal_denials
WHEN NOT EXISTS(SELECT 1 FROM prepared_intents WHERE id=NEW.prepared_intent_id AND ((NEW.operation='record_occurrence' AND intent_kind='record_risk_occurrence') OR (NEW.operation='close' AND intent_kind='close_risk')))
 OR NOT EXISTS(SELECT 1 FROM prepared_intent_targets WHERE prepared_intent_id=NEW.prepared_intent_id AND ordinal=0 AND target_type='risk' AND target_id=NEW.risk_id AND expected_version=NEW.risk_version)
 OR NOT EXISTS(SELECT 1 FROM audit_events WHERE id=NEW.policy_denial_audit_id AND correlation_id=NEW.correlation_id AND actor='head_of_products' AND module='work_management' AND target_type='risk' AND target_id=NEW.risk_id AND policy_outcome='denied' AND approval_outcome='not_required' AND execution_outcome='not_attempted' AND effect_scope='none')
 OR EXISTS(SELECT 1 FROM audit_effects WHERE audit_event_id=NEW.policy_denial_audit_id)
BEGIN SELECT RAISE(ABORT,'risk H2a v11 terminal denial topology is invalid'); END;
CREATE TRIGGER decision_h2a_prepared_intent_kind_insert AFTER INSERT ON decision_h2a_replay_operations WHEN ((NEW.result_kind='prepared' AND NOT EXISTS(SELECT 1 FROM prepared_intents WHERE id=NEW.result_reference AND intent_kind='resolve_decision_request')) OR (NEW.operation='execute_resolve' AND NOT EXISTS(SELECT 1 FROM prepared_intents WHERE id=NEW.prepared_intent_id AND intent_kind='resolve_decision_request'))) BEGIN SELECT RAISE(ABORT,'decision H2a replay must reference a resolve Decision Request prepared intent'); END;
CREATE TRIGGER decision_h2a_prepared_intent_kind_update AFTER UPDATE OF operation,result_kind,result_reference,prepared_intent_id ON decision_h2a_replay_operations WHEN ((NEW.result_kind='prepared' AND NOT EXISTS(SELECT 1 FROM prepared_intents WHERE id=NEW.result_reference AND intent_kind='resolve_decision_request')) OR (NEW.operation='execute_resolve' AND NOT EXISTS(SELECT 1 FROM prepared_intents WHERE id=NEW.prepared_intent_id AND intent_kind='resolve_decision_request'))) BEGIN SELECT RAISE(ABORT,'decision H2a replay must reference a resolve Decision Request prepared intent'); END;
CREATE TRIGGER risk_h2a_lower_classification_terminal_denials_topology_insert BEFORE INSERT ON risk_h2a_lower_classification_terminal_denials
WHEN NOT EXISTS(SELECT 1 FROM prepared_intents WHERE id=NEW.prepared_intent_id AND intent_kind='lower_risk_classification')
 OR NOT EXISTS(SELECT 1 FROM prepared_intent_targets WHERE prepared_intent_id=NEW.prepared_intent_id AND ordinal=0 AND target_type='risk' AND target_id=NEW.risk_id AND expected_version=NEW.risk_version)
 OR NOT EXISTS(SELECT 1 FROM audit_events WHERE id=NEW.policy_denial_audit_id AND correlation_id=NEW.correlation_id AND actor='head_of_products' AND module='work_management' AND target_type='risk' AND target_id=NEW.risk_id AND policy_outcome='denied' AND approval_outcome='not_required' AND execution_outcome='not_attempted' AND effect_scope='none')
 OR EXISTS(SELECT 1 FROM audit_effects WHERE audit_event_id=NEW.policy_denial_audit_id)
BEGIN SELECT RAISE(ABORT,'risk H2a lower-classification terminal denial topology is invalid'); END;
"#;

