/// v46: durable H2a rejection for Risk and Issue (the Action/Decision half
/// landed in v45). Each namespace gains one **independent** stream --
/// `<ns>_reject_prepared_command_results` with its own contiguous-from-zero
/// ordinal and immutable-ordinal triggers -- rather than joining a namespace
/// global stream: Risk and Issue were built as separate generation-specific
/// replay streams (`risk_h2a_v13/v14_*`, `issue_h2a_prepare/execute_*`) and
/// rewriting every existing allocator to a global union would re-create the
/// allocator/trigger drift class fixed in a2ff7a4 for no product requirement.
///
/// The binding triggers admit a rejection only when it consumes a prepared
/// intent of that namespace's own kinds at the same instant
/// (`consumed_at = rejected_at`), exactly as v45 does for Action/Decision.
/// No existing table is touched, so no populated recreate is needed.
pub(super) const V46_RISK_ISSUE_PREPARED_REJECTION_SQL: &str = r#"
CREATE TABLE risk_reject_prepared_command_results(operation TEXT NOT NULL CHECK(operation='reject_prepared'),idempotency_id TEXT PRIMARY KEY,correlation_id TEXT NOT NULL CHECK(length(correlation_id)>0),operation_ordinal INTEGER NOT NULL UNIQUE CHECK(operation_ordinal>=0),prepared_intent_id TEXT NOT NULL UNIQUE REFERENCES prepared_intents(id),actor TEXT NOT NULL CHECK(actor='head_of_products'),rejected_at INTEGER NOT NULL CHECK(rejected_at>=0),audit_event_id TEXT NOT NULL UNIQUE REFERENCES audit_events(id),UNIQUE(idempotency_id,correlation_id),FOREIGN KEY(audit_event_id,correlation_id) REFERENCES audit_events(id,correlation_id)) STRICT;
CREATE INDEX idx_risk_reject_prepared_ordinal ON risk_reject_prepared_command_results(operation_ordinal);
CREATE INDEX idx_risk_reject_prepared_correlation ON risk_reject_prepared_command_results(correlation_id);
CREATE TRIGGER ledger_idempotency_claim_risk_reject_prepared AFTER INSERT ON risk_reject_prepared_command_results BEGIN INSERT INTO ledger_idempotency_claims(idempotency_id,namespace,operation) VALUES(NEW.idempotency_id,'risk',NEW.operation); END;
CREATE TRIGGER risk_reject_prepared_command_results_contiguous_insert BEFORE INSERT ON risk_reject_prepared_command_results WHEN NEW.operation_ordinal != COALESCE((SELECT MAX(operation_ordinal)+1 FROM risk_reject_prepared_command_results),0) BEGIN SELECT RAISE(ABORT,'risk rejection ordinals must be contiguous from zero'); END;
CREATE TRIGGER risk_reject_prepared_command_results_ordinal_immutable BEFORE UPDATE OF operation_ordinal ON risk_reject_prepared_command_results WHEN NEW.operation_ordinal != OLD.operation_ordinal BEGIN SELECT RAISE(ABORT,'risk rejection ordinals are immutable'); END;
CREATE TRIGGER risk_reject_prepared_binding_insert AFTER INSERT ON risk_reject_prepared_command_results WHEN NOT EXISTS(SELECT 1 FROM prepared_intents WHERE id=NEW.prepared_intent_id AND intent_kind IN ('record_risk_occurrence','close_risk') AND consumed_at=NEW.rejected_at) BEGIN SELECT RAISE(ABORT,'risk rejection must consume a matching prepared intent'); END;
CREATE TRIGGER risk_reject_prepared_binding_update AFTER UPDATE OF prepared_intent_id,rejected_at ON risk_reject_prepared_command_results WHEN NOT EXISTS(SELECT 1 FROM prepared_intents WHERE id=NEW.prepared_intent_id AND intent_kind IN ('record_risk_occurrence','close_risk') AND consumed_at=NEW.rejected_at) BEGIN SELECT RAISE(ABORT,'risk rejection must consume a matching prepared intent'); END;
CREATE TABLE issue_reject_prepared_command_results(operation TEXT NOT NULL CHECK(operation='reject_prepared'),idempotency_id TEXT PRIMARY KEY,correlation_id TEXT NOT NULL CHECK(length(correlation_id)>0),operation_ordinal INTEGER NOT NULL UNIQUE CHECK(operation_ordinal>=0),prepared_intent_id TEXT NOT NULL UNIQUE REFERENCES prepared_intents(id),actor TEXT NOT NULL CHECK(actor='head_of_products'),rejected_at INTEGER NOT NULL CHECK(rejected_at>=0),audit_event_id TEXT NOT NULL UNIQUE REFERENCES audit_events(id),UNIQUE(idempotency_id,correlation_id),FOREIGN KEY(audit_event_id,correlation_id) REFERENCES audit_events(id,correlation_id)) STRICT;
CREATE INDEX idx_issue_reject_prepared_ordinal ON issue_reject_prepared_command_results(operation_ordinal);
CREATE INDEX idx_issue_reject_prepared_correlation ON issue_reject_prepared_command_results(correlation_id);
CREATE TRIGGER ledger_idempotency_claim_issue_reject_prepared AFTER INSERT ON issue_reject_prepared_command_results BEGIN INSERT INTO ledger_idempotency_claims(idempotency_id,namespace,operation) VALUES(NEW.idempotency_id,'issue',NEW.operation); END;
CREATE TRIGGER issue_reject_prepared_command_results_contiguous_insert BEFORE INSERT ON issue_reject_prepared_command_results WHEN NEW.operation_ordinal != COALESCE((SELECT MAX(operation_ordinal)+1 FROM issue_reject_prepared_command_results),0) BEGIN SELECT RAISE(ABORT,'issue rejection ordinals must be contiguous from zero'); END;
CREATE TRIGGER issue_reject_prepared_command_results_ordinal_immutable BEFORE UPDATE OF operation_ordinal ON issue_reject_prepared_command_results WHEN NEW.operation_ordinal != OLD.operation_ordinal BEGIN SELECT RAISE(ABORT,'issue rejection ordinals are immutable'); END;
CREATE TRIGGER issue_reject_prepared_binding_insert AFTER INSERT ON issue_reject_prepared_command_results WHEN NOT EXISTS(SELECT 1 FROM prepared_intents WHERE id=NEW.prepared_intent_id AND intent_kind IN ('resolve_issue','close_issue','reopen_issue') AND consumed_at=NEW.rejected_at) BEGIN SELECT RAISE(ABORT,'issue rejection must consume a matching prepared intent'); END;
CREATE TRIGGER issue_reject_prepared_binding_update AFTER UPDATE OF prepared_intent_id,rejected_at ON issue_reject_prepared_command_results WHEN NOT EXISTS(SELECT 1 FROM prepared_intents WHERE id=NEW.prepared_intent_id AND intent_kind IN ('resolve_issue','close_issue','reopen_issue') AND consumed_at=NEW.rejected_at) BEGIN SELECT RAISE(ABORT,'issue rejection must consume a matching prepared intent'); END;
"#;

/// Append-only v47: the record-entry foundation (DG3 record-entry amendment
/// §3.6, §4; product owner 2026-09-21/22). `record_id_reservations` holds
/// the record id the host minted for one `clientRequestId`, so a retry builds
/// the same create command; rows are immutable and never removed. The three
/// `risk_response_*` tables give `UpdateRiskResponse` the same typed
/// command / result / audit replay authority every other Risk command has,
/// with the response the update produced stored as the result — a later
/// update or transition must not change what a replay of this one returns.
/// No existing table is touched, so no populated recreate is needed.
pub(super) const V47_RECORD_ENTRY_FOUNDATION_SQL: &str = r#"
CREATE TABLE record_id_reservations(idempotency_id TEXT PRIMARY KEY CHECK(length(idempotency_id)>0),namespace TEXT NOT NULL CHECK(namespace IN ('portfolio','delivery','people','action','decision','risk','issue','relationship')),operation TEXT NOT NULL CHECK(length(operation)>0),entity_kind TEXT NOT NULL CHECK(entity_kind IN ('portfolio','product','initiative','project','roadmap','milestone','kpi_definition','kpi_observation','stakeholder','action_request','decision_request','risk','issue','relationship')),generated_id TEXT NOT NULL UNIQUE CHECK(length(generated_id)>0),reserved_at INTEGER NOT NULL CHECK(reserved_at>=0),UNIQUE(idempotency_id,namespace,operation,entity_kind)) STRICT;
CREATE TRIGGER record_id_reservations_immutable BEFORE UPDATE ON record_id_reservations BEGIN SELECT RAISE(ABORT,'record id reservations are immutable'); END;
CREATE TRIGGER record_id_reservations_no_delete BEFORE DELETE ON record_id_reservations BEGIN SELECT RAISE(ABORT,'record id reservations are never removed'); END;
CREATE TABLE risk_response_replay_operations(idempotency_id TEXT PRIMARY KEY,operation TEXT NOT NULL CHECK(operation='update_risk_response'),correlation_id TEXT NOT NULL CHECK(length(correlation_id)>0),operation_ordinal INTEGER NOT NULL UNIQUE CHECK(operation_ordinal>=0),result_reference TEXT NOT NULL REFERENCES risks(id),result_classification TEXT NOT NULL CHECK(result_classification IN ('public','internal','confidential','restricted')),result_response TEXT NOT NULL CHECK(result_response IN ('avoid','mitigate','accept','transfer')),result_owner_id TEXT REFERENCES stakeholders(id),result_rationale TEXT,result_residual_exposure TEXT,result_next_review_at INTEGER CHECK(result_next_review_at IS NULL OR result_next_review_at>=0),result_in_exception_queue INTEGER NOT NULL CHECK(result_in_exception_queue IN (0,1)),result_version INTEGER NOT NULL CHECK(result_version>1),UNIQUE(idempotency_id,correlation_id),UNIQUE(result_reference,result_version),CHECK(result_response NOT IN ('accept','transfer') OR (result_owner_id IS NOT NULL AND result_rationale IS NOT NULL AND result_residual_exposure IS NOT NULL AND result_next_review_at IS NOT NULL)),CHECK(result_in_exception_queue=(CASE WHEN result_response IN ('accept','transfer') THEN 0 ELSE 1 END))) STRICT;
CREATE TABLE risk_response_command_updates(idempotency_id TEXT PRIMARY KEY REFERENCES risk_response_replay_operations(idempotency_id),risk_id TEXT NOT NULL REFERENCES risks(id),expected_version INTEGER NOT NULL CHECK(expected_version>0),response TEXT NOT NULL CHECK(response IN ('avoid','mitigate','accept','transfer')),owner_id TEXT REFERENCES stakeholders(id),rationale TEXT,residual_exposure TEXT,next_review_at INTEGER CHECK(next_review_at IS NULL OR next_review_at>=0)) STRICT;
CREATE TABLE risk_response_replay_audits(idempotency_id TEXT PRIMARY KEY REFERENCES risk_response_replay_operations(idempotency_id),audit_event_id TEXT NOT NULL UNIQUE REFERENCES audit_events(id),correlation_id TEXT NOT NULL,FOREIGN KEY(audit_event_id,correlation_id) REFERENCES audit_events(id,correlation_id),FOREIGN KEY(idempotency_id,correlation_id) REFERENCES risk_response_replay_operations(idempotency_id,correlation_id)) STRICT;
CREATE INDEX idx_risk_response_replay_ordinal ON risk_response_replay_operations(operation_ordinal);
CREATE INDEX idx_risk_response_replay_correlation ON risk_response_replay_operations(correlation_id);
CREATE INDEX idx_risk_response_replay_risk ON risk_response_replay_operations(result_reference);
CREATE TRIGGER ledger_idempotency_claim_risk_response AFTER INSERT ON risk_response_replay_operations BEGIN INSERT INTO ledger_idempotency_claims(idempotency_id,namespace,operation) VALUES(NEW.idempotency_id,'risk',NEW.operation); END;
CREATE TRIGGER risk_response_replay_operations_contiguous_insert BEFORE INSERT ON risk_response_replay_operations WHEN NEW.operation_ordinal != COALESCE((SELECT MAX(operation_ordinal)+1 FROM risk_response_replay_operations),0) BEGIN SELECT RAISE(ABORT,'risk response operation ordinals must be contiguous from zero'); END;
CREATE TRIGGER risk_response_replay_operations_ordinal_immutable BEFORE UPDATE OF operation_ordinal ON risk_response_replay_operations WHEN NEW.operation_ordinal != OLD.operation_ordinal BEGIN SELECT RAISE(ABORT,'risk response operation ordinals are immutable'); END;
"#;

/// Append-only v48: Evidence from a file (DG3 Vault-root and
/// Evidence-from-file amendment §4, §6 item 4; product owner 2026-09-23).
/// Evidence references join the durable id reservation: its two CHECK lists
/// gain the `evidence` namespace and the `evidence_reference` kind, which
/// SQLite can only change by rebuilding the table — create the new one, copy
/// every row, drop the old (its two triggers go with it), rename, and put
/// the triggers back. Nothing references the table by foreign key, and the
/// upgrade runs with foreign keys off. Then the two reads' indexes: the exact
/// Vault-relative path (the fast path; Windows-equivalent spellings are
/// found by the Ledger's read, which compares every path the way Windows
/// does — the index alone does not make paths unique), and the pinned
/// fingerprint, for the "same content elsewhere" warning.
pub(super) const V48_EVIDENCE_FROM_FILE_SQL: &str = r#"
CREATE TABLE record_id_reservations_v48(idempotency_id TEXT PRIMARY KEY CHECK(length(idempotency_id)>0),namespace TEXT NOT NULL CHECK(namespace IN ('portfolio','delivery','people','action','decision','risk','issue','relationship','evidence')),operation TEXT NOT NULL CHECK(length(operation)>0),entity_kind TEXT NOT NULL CHECK(entity_kind IN ('portfolio','product','initiative','project','roadmap','milestone','kpi_definition','kpi_observation','stakeholder','action_request','decision_request','risk','issue','relationship','evidence_reference')),generated_id TEXT NOT NULL UNIQUE CHECK(length(generated_id)>0),reserved_at INTEGER NOT NULL CHECK(reserved_at>=0),UNIQUE(idempotency_id,namespace,operation,entity_kind)) STRICT;
INSERT INTO record_id_reservations_v48(idempotency_id,namespace,operation,entity_kind,generated_id,reserved_at) SELECT idempotency_id,namespace,operation,entity_kind,generated_id,reserved_at FROM record_id_reservations;
DROP TABLE record_id_reservations;
ALTER TABLE record_id_reservations_v48 RENAME TO record_id_reservations;
CREATE TRIGGER record_id_reservations_immutable BEFORE UPDATE ON record_id_reservations BEGIN SELECT RAISE(ABORT,'record id reservations are immutable'); END;
CREATE TRIGGER record_id_reservations_no_delete BEFORE DELETE ON record_id_reservations BEGIN SELECT RAISE(ABORT,'record id reservations are never removed'); END;
CREATE INDEX idx_evidence_references_vault_relative_path ON evidence_references(vault_relative_path);
CREATE INDEX idx_evidence_references_fingerprint ON evidence_references(fingerprint_algorithm,fingerprint_digest) WHERE fingerprint_algorithm IS NOT NULL AND fingerprint_digest IS NOT NULL;
"#;

pub(super) const V3_DECISION_H1_SQL: &str = r#"
CREATE TABLE ledger_idempotency_claims(idempotency_id TEXT PRIMARY KEY,namespace TEXT NOT NULL,operation TEXT NOT NULL) STRICT;
INSERT INTO ledger_idempotency_claims(idempotency_id,namespace,operation) SELECT idempotency_id,'action',operation FROM action_replay_operations;
INSERT INTO ledger_idempotency_claims(idempotency_id,namespace,operation) SELECT idempotency_id,'relationship',operation FROM relationship_replay_operations;
INSERT INTO ledger_idempotency_claims(idempotency_id,namespace,operation) SELECT idempotency_id,namespace,operation FROM idempotency_outcomes;
CREATE TRIGGER ledger_idempotency_claim_action AFTER INSERT ON action_replay_operations BEGIN INSERT INTO ledger_idempotency_claims(idempotency_id,namespace,operation) VALUES(NEW.idempotency_id,'action',NEW.operation); END;
CREATE TRIGGER ledger_idempotency_claim_relationship AFTER INSERT ON relationship_replay_operations BEGIN INSERT INTO ledger_idempotency_claims(idempotency_id,namespace,operation) VALUES(NEW.idempotency_id,'relationship',NEW.operation); END;
CREATE TRIGGER ledger_idempotency_claim_outcome AFTER INSERT ON idempotency_outcomes BEGIN INSERT INTO ledger_idempotency_claims(idempotency_id,namespace,operation) VALUES(NEW.idempotency_id,NEW.namespace,NEW.operation); END;
CREATE TRIGGER ledger_idempotency_claim_operation AFTER INSERT ON operations BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM ledger_idempotency_claims WHERE idempotency_id=NEW.idempotency_id AND (namespace!=NEW.namespace OR operation!=NEW.operation)) THEN RAISE(ABORT,'global idempotency collision') END; INSERT OR IGNORE INTO ledger_idempotency_claims(idempotency_id,namespace,operation) VALUES(NEW.idempotency_id,NEW.namespace,NEW.operation); END;
CREATE TABLE decision_replay_operations(idempotency_id TEXT PRIMARY KEY,operation TEXT NOT NULL CHECK(operation IN ('create_request','transition_request')),correlation_id TEXT NOT NULL,operation_ordinal INTEGER NOT NULL CHECK(operation_ordinal>=0),result_reference TEXT NOT NULL REFERENCES decision_requests(id),UNIQUE(operation_ordinal),UNIQUE(idempotency_id,correlation_id)) STRICT;
CREATE TRIGGER ledger_idempotency_claim_decision AFTER INSERT ON decision_replay_operations BEGIN INSERT INTO ledger_idempotency_claims(idempotency_id,namespace,operation) VALUES(NEW.idempotency_id,'decision',NEW.operation); END;
CREATE TABLE decision_command_create_requests(idempotency_id TEXT PRIMARY KEY REFERENCES decision_replay_operations(idempotency_id),request_id TEXT NOT NULL REFERENCES decision_requests(id),subject TEXT NOT NULL,details TEXT NOT NULL,intended_owner_id TEXT REFERENCES stakeholders(id),classification TEXT NOT NULL CHECK(classification IN ('public','internal','confidential','restricted','unclassified'))) STRICT;
CREATE TABLE decision_request_transitions(request_id TEXT NOT NULL REFERENCES decision_requests(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),from_state TEXT NOT NULL CHECK(from_state IN ('draft','open','resolved','withdrawn')),to_state TEXT NOT NULL CHECK(to_state IN ('draft','open','resolved','withdrawn')),rationale TEXT,occurred_at INTEGER NOT NULL CHECK(occurred_at>=0),PRIMARY KEY(request_id,ordinal),CHECK((to_state='open' AND from_state='draft' AND rationale IS NULL) OR (to_state='withdrawn' AND from_state='open' AND rationale IS NOT NULL))) STRICT;
CREATE TABLE decision_command_transition_requests(idempotency_id TEXT PRIMARY KEY REFERENCES decision_replay_operations(idempotency_id),request_id TEXT NOT NULL REFERENCES decision_requests(id),expected_version INTEGER NOT NULL CHECK(expected_version>0),target_state TEXT NOT NULL CHECK(target_state IN ('open','withdrawn')),rationale TEXT,CHECK((target_state='open' AND rationale IS NULL) OR (target_state='withdrawn' AND rationale IS NOT NULL))) STRICT;
CREATE TABLE decision_replay_audits(idempotency_id TEXT NOT NULL REFERENCES decision_replay_operations(idempotency_id),ordinal INTEGER NOT NULL CHECK(ordinal=0),audit_event_id TEXT NOT NULL UNIQUE REFERENCES audit_events(id),correlation_id TEXT NOT NULL,PRIMARY KEY(idempotency_id,ordinal),FOREIGN KEY(audit_event_id,correlation_id) REFERENCES audit_events(id,correlation_id),FOREIGN KEY(idempotency_id,correlation_id) REFERENCES decision_replay_operations(idempotency_id,correlation_id)) STRICT;
CREATE TRIGGER decision_replay_operations_contiguous_insert BEFORE INSERT ON decision_replay_operations WHEN NEW.operation_ordinal != COALESCE((SELECT MAX(operation_ordinal)+1 FROM decision_replay_operations),0) BEGIN SELECT RAISE(ABORT,'decision replay operation ordinals must be contiguous from zero'); END;
CREATE TRIGGER decision_replay_operations_ordinal_immutable BEFORE UPDATE OF operation_ordinal ON decision_replay_operations WHEN NEW.operation_ordinal != OLD.operation_ordinal BEGIN SELECT RAISE(ABORT,'decision replay operation ordinals are immutable'); END;
"#;

/// Append-only v4 Decision H2a resolve replay authority.  This delta leaves
/// the released v1--v3 migration sources immutable and uses the existing
/// normalized Prepared Intent, Decision, Action Request, Approval Receipt, and
/// Audit Event records as the authoritative state.
pub(super) const V4_DECISION_H2A_RESOLVE_SQL: &str = r#"
CREATE TABLE decision_h2a_replay_operations(idempotency_id TEXT PRIMARY KEY,operation TEXT NOT NULL CHECK(operation IN ('prepare_resolve','execute_resolve')),correlation_id TEXT NOT NULL CHECK(length(correlation_id)>0),operation_ordinal INTEGER NOT NULL UNIQUE CHECK(operation_ordinal>=0),result_kind TEXT NOT NULL CHECK(result_kind IN ('prepared','resolved','terminal')),result_reference TEXT,prepared_result_id TEXT GENERATED ALWAYS AS (CASE WHEN result_kind='prepared' THEN result_reference END) STORED,decision_result_id TEXT GENERATED ALWAYS AS (CASE WHEN result_kind='resolved' THEN result_reference END) STORED,prepared_intent_id TEXT REFERENCES prepared_intents(id),approval_receipt_id TEXT UNIQUE REFERENCES approval_receipts(id),terminal_cause TEXT CHECK(terminal_cause IN ('not_found','illegal_transition','stale_version','invalid_evidence','idempotency_conflict','prepared_intent_not_found','prepared_intent_changed','unauthorized','digest_mismatch','expired','policy_denied','infrastructure_failure')),attempted_digest TEXT,error_code TEXT CHECK(error_code IN ('VALIDATION_INVALID_FIELD','DOMAIN_CONFLICT','DOMAIN_NOT_FOUND','SECURITY_POLICY_DENIED','SECURITY_PREVIEW_EXPIRED_OR_CHANGED','DOMAIN_IDEMPOTENCY_CONFLICT','PLATFORM_INTERNAL')),error_message_key TEXT,error_correlation_id TEXT,error_retryable INTEGER CHECK(error_retryable IN(0,1)),prepare_resolve_child_id TEXT GENERATED ALWAYS AS (CASE WHEN operation='prepare_resolve' THEN idempotency_id END) STORED,execute_resolve_child_id TEXT GENERATED ALWAYS AS (CASE WHEN operation='execute_resolve' THEN idempotency_id END) STORED,UNIQUE(idempotency_id,operation),UNIQUE(idempotency_id,correlation_id),UNIQUE(idempotency_id,prepared_intent_id),FOREIGN KEY(prepared_result_id) REFERENCES prepared_intents(id),FOREIGN KEY(decision_result_id) REFERENCES decisions(id),FOREIGN KEY(prepared_intent_id) REFERENCES prepared_intents(id),FOREIGN KEY(prepare_resolve_child_id,operation) REFERENCES decision_h2a_command_prepare_resolves(idempotency_id,command_kind) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(execute_resolve_child_id,operation) REFERENCES decision_h2a_command_execute_resolves(idempotency_id,command_kind) DEFERRABLE INITIALLY DEFERRED,CHECK((operation='prepare_resolve' AND result_kind IN ('prepared','terminal')) OR (operation='execute_resolve' AND result_kind IN ('resolved','terminal'))),CHECK((result_kind='terminal')=(result_reference IS NULL)),CHECK((result_kind='terminal')=(terminal_cause IS NOT NULL)),CHECK((terminal_cause='digest_mismatch')=(attempted_digest IS NOT NULL)),CHECK((result_kind='terminal')=(error_code IS NOT NULL AND error_message_key IS NOT NULL AND error_correlation_id IS NOT NULL AND error_retryable IS NOT NULL)),CHECK(error_correlation_id IS NULL OR error_correlation_id=correlation_id),CHECK((result_kind='terminal') OR (terminal_cause IS NULL AND attempted_digest IS NULL AND error_code IS NULL AND error_message_key IS NULL AND error_correlation_id IS NULL AND error_retryable IS NULL)),CHECK((result_kind='resolved')=(approval_receipt_id IS NOT NULL)),CHECK((operation='prepare_resolve' AND ((result_kind='prepared' AND prepared_intent_id IS NULL) OR (result_kind='terminal' AND prepared_intent_id IS NULL))) OR (operation='execute_resolve' AND prepared_intent_id IS NOT NULL))) STRICT;
CREATE TABLE decision_h2a_command_prepare_resolves(idempotency_id TEXT PRIMARY KEY,command_kind TEXT GENERATED ALWAYS AS ('prepare_resolve') STORED,request_id TEXT NOT NULL REFERENCES decision_requests(id),expected_version INTEGER NOT NULL CHECK(expected_version>0),statement TEXT NOT NULL,rationale TEXT NOT NULL,impact TEXT NOT NULL,UNIQUE(idempotency_id,command_kind),FOREIGN KEY(idempotency_id,command_kind) REFERENCES decision_h2a_replay_operations(idempotency_id,operation)) STRICT;
CREATE TABLE decision_h2a_command_execute_resolves(idempotency_id TEXT PRIMARY KEY,command_kind TEXT GENERATED ALWAYS AS ('execute_resolve') STORED,prepared_id TEXT NOT NULL REFERENCES prepared_intents(id),actor TEXT NOT NULL CHECK(actor='head_of_products'),acknowledged_digest TEXT NOT NULL,UNIQUE(idempotency_id,command_kind),FOREIGN KEY(idempotency_id,command_kind) REFERENCES decision_h2a_replay_operations(idempotency_id,operation)) STRICT;
CREATE TABLE decision_h2a_replay_audits(idempotency_id TEXT NOT NULL REFERENCES decision_h2a_replay_operations(idempotency_id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),audit_event_id TEXT NOT NULL UNIQUE REFERENCES audit_events(id),correlation_id TEXT NOT NULL,PRIMARY KEY(idempotency_id,ordinal),FOREIGN KEY(audit_event_id,correlation_id) REFERENCES audit_events(id,correlation_id),FOREIGN KEY(idempotency_id,correlation_id) REFERENCES decision_h2a_replay_operations(idempotency_id,correlation_id)) STRICT;
CREATE TRIGGER ledger_idempotency_claim_decision_h2a AFTER INSERT ON decision_h2a_replay_operations BEGIN INSERT INTO ledger_idempotency_claims(idempotency_id,namespace,operation) VALUES(NEW.idempotency_id,'decision',NEW.operation); END;
CREATE TRIGGER decision_replay_operations_contiguous_global_v4 BEFORE INSERT ON decision_replay_operations WHEN NEW.operation_ordinal != COALESCE((SELECT MAX(operation_ordinal)+1 FROM (SELECT operation_ordinal FROM decision_replay_operations UNION ALL SELECT operation_ordinal FROM decision_h2a_replay_operations)),0) BEGIN SELECT RAISE(ABORT,'decision replay operation ordinals must be globally contiguous from zero'); END;
CREATE TRIGGER decision_h2a_replay_operations_contiguous_insert BEFORE INSERT ON decision_h2a_replay_operations WHEN NEW.operation_ordinal != COALESCE((SELECT MAX(operation_ordinal)+1 FROM (SELECT operation_ordinal FROM decision_replay_operations UNION ALL SELECT operation_ordinal FROM decision_h2a_replay_operations)),0) BEGIN SELECT RAISE(ABORT,'decision replay operation ordinals must be globally contiguous from zero'); END;
CREATE TRIGGER decision_h2a_replay_operations_ordinal_immutable BEFORE UPDATE OF operation_ordinal ON decision_h2a_replay_operations WHEN NEW.operation_ordinal != OLD.operation_ordinal BEGIN SELECT RAISE(ABORT,'decision replay operation ordinals are immutable'); END;
CREATE TRIGGER decision_h2a_prepared_intent_kind_insert AFTER INSERT ON decision_h2a_replay_operations WHEN ((NEW.result_kind='prepared' AND NOT EXISTS(SELECT 1 FROM prepared_intents WHERE id=NEW.result_reference AND intent_kind='resolve_decision_request')) OR (NEW.operation='execute_resolve' AND NOT EXISTS(SELECT 1 FROM prepared_intents WHERE id=NEW.prepared_intent_id AND intent_kind='resolve_decision_request'))) BEGIN SELECT RAISE(ABORT,'decision H2a replay must reference a resolve Decision Request prepared intent'); END;
CREATE TRIGGER decision_h2a_prepared_intent_kind_update AFTER UPDATE OF operation,result_kind,result_reference,prepared_intent_id ON decision_h2a_replay_operations WHEN ((NEW.result_kind='prepared' AND NOT EXISTS(SELECT 1 FROM prepared_intents WHERE id=NEW.result_reference AND intent_kind='resolve_decision_request')) OR (NEW.operation='execute_resolve' AND NOT EXISTS(SELECT 1 FROM prepared_intents WHERE id=NEW.prepared_intent_id AND intent_kind='resolve_decision_request'))) BEGIN SELECT RAISE(ABORT,'decision H2a replay must reference a resolve Decision Request prepared intent'); END;
CREATE TRIGGER decision_h2a_execute_binding_insert AFTER INSERT ON decision_h2a_replay_operations WHEN NEW.operation='execute_resolve' AND EXISTS(SELECT 1 FROM decision_h2a_command_execute_resolves WHERE idempotency_id=NEW.idempotency_id AND prepared_id IS NOT NEW.prepared_intent_id) BEGIN SELECT RAISE(ABORT,'execute_resolve prepared intent does not match its typed command'); END;
CREATE TRIGGER decision_h2a_execute_binding_update AFTER UPDATE OF operation,prepared_intent_id ON decision_h2a_replay_operations WHEN NEW.operation='execute_resolve' AND EXISTS(SELECT 1 FROM decision_h2a_command_execute_resolves WHERE idempotency_id=NEW.idempotency_id AND prepared_id IS NOT NEW.prepared_intent_id) BEGIN SELECT RAISE(ABORT,'execute_resolve prepared intent does not match its typed command'); END;
CREATE TRIGGER decision_h2a_command_execute_binding_insert AFTER INSERT ON decision_h2a_command_execute_resolves WHEN EXISTS(SELECT 1 FROM decision_h2a_replay_operations WHERE idempotency_id=NEW.idempotency_id AND operation='execute_resolve' AND prepared_intent_id IS NOT NEW.prepared_id) BEGIN SELECT RAISE(ABORT,'execute_resolve prepared intent does not match its typed command'); END;
CREATE TRIGGER decision_h2a_command_execute_binding_update AFTER UPDATE OF idempotency_id,prepared_id ON decision_h2a_command_execute_resolves WHEN EXISTS(SELECT 1 FROM decision_h2a_replay_operations WHERE idempotency_id=NEW.idempotency_id AND operation='execute_resolve' AND prepared_intent_id IS NOT NEW.prepared_id) BEGIN SELECT RAISE(ABORT,'execute_resolve prepared intent does not match its typed command'); END;
CREATE INDEX idx_decision_h2a_replay_ordinal ON decision_h2a_replay_operations(operation_ordinal);
CREATE INDEX idx_decision_h2a_replay_correlation ON decision_h2a_replay_operations(correlation_id);
"#;

