#[derive(Debug, Eq, PartialEq)]
pub(super) struct SchemaObject {
    object_type: String,
    name: String,
    table_name: String,
    sql: Option<String>,
}

pub(super) fn schema_objects(
    connection: &Connection,
) -> Result<Vec<SchemaObject>, LedgerOpenError> {
    let mut statement = connection
        .prepare("SELECT type,name,tbl_name,sql FROM sqlite_schema WHERE name NOT LIKE 'sqlite_%' ORDER BY type,name")
        .map_err(classify_inspection_error)?;
    let objects = statement
        .query_map([], |row| {
            Ok(SchemaObject {
                object_type: row.get(0)?,
                name: row.get(1)?,
                table_name: row.get(2)?,
                sql: row.get(3)?,
            })
        })
        .map_err(classify_inspection_error)?
        .collect::<Result<Vec<_>, _>>()
        .map_err(classify_inspection_error)?;
    Ok(objects)
}

pub(super) fn validate_canonical_schema(connection: &Connection) -> Result<(), LedgerOpenError> {
    if schema_objects(connection)? != *expected_schema_objects()? {
        return Err(LedgerOpenError::InvalidMetadata);
    }
    Ok(())
}

/// The canonical schema is a pure function of the migration SQL compiled into this binary, so it
/// is built once per process. The live schema is still read and compared on every call.
fn expected_schema_objects() -> Result<&'static Vec<SchemaObject>, LedgerOpenError> {
    static EXPECTED: OnceLock<Vec<SchemaObject>> = OnceLock::new();
    if let Some(objects) = EXPECTED.get() {
        return Ok(objects);
    }
    let built = build_expected_schema_objects()?;
    Ok(EXPECTED.get_or_init(|| built))
}

fn build_expected_schema_objects() -> Result<Vec<SchemaObject>, LedgerOpenError> {
    schema_objects_of(super::migrations::production_descriptors())
}

/// The schema a Ledger has after exactly these descriptors, in order: built
/// by running their SQL on an empty in-memory database. The same list drives
/// bootstrap, the registry check and this, so the three cannot drift apart.
pub(super) fn schema_objects_of(
    descriptors: &[super::migrations::Migration],
) -> Result<Vec<SchemaObject>, LedgerOpenError> {
    let expected = Connection::open_in_memory().map_err(classify_inspection_error)?;
    for migration in descriptors {
        expected
            .execute_batch(migration.sql)
            .map_err(classify_inspection_error)?;
    }
    schema_objects(&expected)
}

/// Whether the live schema is exactly the one these descriptors produce: a
/// Ledger at an older supported version, or a migration target checked
/// inside its transaction.
pub(super) fn validate_canonical_schema_against(
    connection: &Connection,
    descriptors: &[super::migrations::Migration],
) -> Result<(), LedgerOpenError> {
    if schema_objects(connection)? != schema_objects_of(descriptors)? {
        return Err(LedgerOpenError::InvalidMetadata);
    }
    Ok(())
}
